// Cyrus token economy: every tunable number, as admin Settings (`cyrus_tok_*`).
//
// Pure + client-safe except `loadTokenConfig` (DB read, server only, dynamic import).
// Defaults are the recommended numbers from /root/agent-notes/cyrus-economy/ECONOMY.md;
// docs/DOCUMENTATION.md "Cyrus token economy" explains each one. A Setting row overrides
// its default; a blank or unparseable value falls back to the default (never to 0), so
// a fat-fingered admin edit can't silently make builds free or grants huge.
import type { CyrusModelId } from "../models";

export const TOKEN_TIERS = ["free", "katara", "saka", "all"] as const;
export type TokenTier = (typeof TOKEN_TIERS)[number];
export const PLAN_TIERS = ["katara", "saka", "all"] as const;
export type PlanTier = (typeof PLAN_TIERS)[number];
export const isPlanTier = (v: unknown): v is PlanTier => typeof v === "string" && (PLAN_TIERS as readonly string[]).includes(v);

export type Complexity = "simple" | "standard" | "complex";
export type ReserveTable = Record<CyrusModelId, Record<Complexity, [number, number]>>;

export const DEFAULT_RESERVE_TABLE: ReserveTable = {
  katara: { simple: [30, 70], standard: [60, 140], complex: [100, 240] },
  saka: { simple: [35, 100], standard: [60, 220], complex: [110, 400] },
  yakko: { simple: [100, 250], standard: [200, 500], complex: [400, 1000] },
};

export const CYRUS_TOKEN_DEFAULTS = {
  // --- Launch / gate ---
  /** false = only private-preview accounts (lib/preview-access "modbuilder") earn, see or spend tokens. */
  cyrus_tok_live: "false",
  /** true = a build needs tokens and the plan's model unlock. false = tokens are tracked but never block. */
  cyrus_tok_enforce: "true",
  /** Show "Includes N Cyrus tokens" on game checkout (still preview-only until cyrus_tok_live). */
  cyrus_tok_checkout_line: "true",

  // --- What a token is worth ---
  /** Tokens charged per 1 USD of measured AI cost (build service costUsd). 500 = 1 token per $0.002. */
  cyrus_tok_tokens_per_usd: "500",
  cyrus_tok_mult_katara: "1",
  cyrus_tok_mult_saka: "1",
  /** Yakko premium: heavier variance, holds a build slot ~2x longer. */
  cyrus_tok_mult_yakko: "1.25",
  /** Floor for any build that reached the AI. */
  cyrus_tok_min_spend: "5",
  /** Per model x complexity [typical low, high] tokens; high is what a build reserves. JSON. */
  cyrus_tok_reserve_table: JSON.stringify(DEFAULT_RESERVE_TABLE),

  // --- Failure / abuse ---
  cyrus_tok_charge_refused: "true",
  cyrus_tok_charge_cancelled: "true",
  /** % of the actual cost charged for a build that failed on our side (compile, timeout, outage). */
  cyrus_tok_failed_charge_pct: "0",
  /** Our-side failures that are free per rolling window; after that they are charged in full. */
  cyrus_tok_free_failures: "3",
  cyrus_tok_free_failures_days: "7",
  /** Max tokens reserved+spent per rolling 24 h. */
  cyrus_tok_daily_spend_cap: "5000",
  cyrus_tok_new_account_days: "7",
  cyrus_tok_new_account_daily_cap: "1000",
  /** Below this the UI shows the low-balance state. */
  cyrus_tok_low_balance: "100",
  /** One-time starter tokens for an account that has never held any (verified email, economy live). 0 turns it off. */
  cyrus_tok_starter: "70",
  cyrus_tok_starter_days: "30",

  // --- Game-server grants: amount = clamp(round5(base + perUsd * monthly $), min, max) ---
  cyrus_tok_grant_initial_base: "100",
  cyrus_tok_grant_initial_per_usd: "16",
  cyrus_tok_grant_initial_min: "150",
  cyrus_tok_grant_initial_max: "750",
  cyrus_tok_grant_renew_base: "25",
  cyrus_tok_grant_renew_per_usd: "6",
  cyrus_tok_grant_renew_min: "40",
  cyrus_tok_grant_renew_max: "300",
  /** A prepaid N-month term is granted per month, up to this many months. */
  cyrus_tok_grant_term_months_cap: "12",
  /** Server-grant lots expire after this many days (or the term + 30 d, whichever is longer). */
  cyrus_tok_grant_expiry_days: "90",
  /** Initial grants per account per rolling 30 days (farming many cheap servers). */
  cyrus_tok_grant_max_initial_per_30d: "3",
  /** Max unexpired server-grant tokens one account can hold. */
  cyrus_tok_grant_balance_cap: "3000",

  // --- Plans (Stripe subscriptions, renew monthly, tokens stack) ---
  cyrus_tok_plan_katara_tokens: "750",
  cyrus_tok_plan_saka_tokens: "3500",
  cyrus_tok_plan_all_tokens: "10000",
  /** Display prices + the proration rate. The real charge is the Stripe Price. */
  cyrus_tok_plan_katara_cents: "499",
  cyrus_tok_plan_saka_cents: "1999",
  cyrus_tok_plan_all_cents: "4999",
  /** Each month's plan tokens last this many months (so at most this many months stack). */
  cyrus_tok_plan_rollover_months: "3",
  /** After a plan ends, its tokens stay usable (Katara only) this many days. */
  cyrus_tok_plan_cancel_grace_days: "30",
  /** A failed renewal keeps the unlock this many days past the period end while Stripe retries. */
  cyrus_tok_plan_past_due_grace_days: "3",
  /** Price id overrides; blank = find the price by lookup_key (scripts/cyrus-tokens-stripe-setup.ts). */
  cyrus_tok_price_katara: "",
  cyrus_tok_price_saka: "",
  cyrus_tok_price_all: "",

  // --- One-off top-ups ---
  cyrus_tok_topup_enabled: "true",
  cyrus_tok_topup_tokens_per_usd: "120",
  cyrus_tok_topup_min_cents: "500",
  cyrus_tok_topup_max_cents: "10000",
  cyrus_tok_topup_expiry_days: "365",
  /** true = only accounts with a paid game server or plan may buy a top-up. */
  cyrus_tok_topup_requires_paid: "false",

  // --- Admin ---
  cyrus_tok_admin_grant_expiry_days: "365",
} as const;

export type TokenSettingKey = keyof typeof CYRUS_TOKEN_DEFAULTS;
export const TOKEN_SETTING_KEYS = Object.keys(CYRUS_TOKEN_DEFAULTS) as TokenSettingKey[];

export type TokenConfig = {
  live: boolean;
  enforce: boolean;
  checkoutLine: boolean;
  tokensPerUsd: number;
  mult: Record<CyrusModelId, number>;
  minSpend: number;
  reserve: ReserveTable;
  chargeRefused: boolean;
  chargeCancelled: boolean;
  failedChargePct: number;
  freeFailures: number;
  freeFailuresDays: number;
  dailyCap: number;
  newAccountDays: number;
  newAccountDailyCap: number;
  lowBalance: number;
  starterTokens: number;
  starterDays: number;
  grant: {
    initial: { base: number; perUsd: number; min: number; max: number };
    renew: { base: number; perUsd: number; min: number; max: number };
    termMonthsCap: number;
    expiryDays: number;
    maxInitialPer30d: number;
    balanceCap: number;
  };
  plan: {
    tokens: Record<PlanTier, number>;
    cents: Record<PlanTier, number>;
    rolloverMonths: number;
    cancelGraceDays: number;
    pastDueGraceDays: number;
    priceIds: Record<PlanTier, string>;
  };
  topup: { enabled: boolean; tokensPerUsd: number; minCents: number; maxCents: number; expiryDays: number; requiresPaid: boolean };
  adminGrantExpiryDays: number;
};

function num(raw: string | undefined, def: string, { min = 0, max = Number.MAX_SAFE_INTEGER } = {}): number {
  const n = Number(raw);
  const d = Number(def);
  if (raw === undefined || raw.trim() === "" || !Number.isFinite(n)) return d;
  return Math.min(max, Math.max(min, n));
}
function bool(raw: string | undefined, def: string): boolean {
  const v = (raw ?? def).trim().toLowerCase();
  return v === "true" || v === "1" || v === "on";
}

function parseReserve(raw: string | undefined): ReserveTable {
  const out: ReserveTable = JSON.parse(JSON.stringify(DEFAULT_RESERVE_TABLE));
  if (!raw) return out;
  try {
    const j = JSON.parse(raw) as Record<string, Record<string, unknown>>;
    for (const m of Object.keys(out) as CyrusModelId[]) {
      for (const c of ["simple", "standard", "complex"] as Complexity[]) {
        const v = j?.[m]?.[c];
        if (Array.isArray(v) && v.length === 2 && v.every((x) => Number.isFinite(Number(x)) && Number(x) > 0)) {
          const lo = Math.round(Number(v[0]));
          const hi = Math.max(lo, Math.round(Number(v[1])));
          out[m][c] = [lo, hi];
        }
      }
    }
  } catch { /* keep defaults */ }
  return out;
}

/** Pure: stored Setting values (any subset) -> typed config. Unit-tested. */
export function parseTokenConfig(stored: Partial<Record<string, string>>): TokenConfig {
  const D = CYRUS_TOKEN_DEFAULTS;
  const g = (k: TokenSettingKey) => stored[k];
  const n = (k: TokenSettingKey, o?: { min?: number; max?: number }) => num(g(k), D[k], o);
  const b = (k: TokenSettingKey) => bool(g(k), D[k]);
  return {
    live: b("cyrus_tok_live"),
    enforce: b("cyrus_tok_enforce"),
    checkoutLine: b("cyrus_tok_checkout_line"),
    tokensPerUsd: n("cyrus_tok_tokens_per_usd", { min: 1, max: 100000 }),
    mult: {
      katara: n("cyrus_tok_mult_katara", { min: 0.1, max: 20 }),
      saka: n("cyrus_tok_mult_saka", { min: 0.1, max: 20 }),
      yakko: n("cyrus_tok_mult_yakko", { min: 0.1, max: 20 }),
    },
    minSpend: Math.round(n("cyrus_tok_min_spend", { max: 10000 })),
    reserve: parseReserve(g("cyrus_tok_reserve_table")),
    chargeRefused: b("cyrus_tok_charge_refused"),
    chargeCancelled: b("cyrus_tok_charge_cancelled"),
    failedChargePct: n("cyrus_tok_failed_charge_pct", { max: 100 }),
    freeFailures: Math.round(n("cyrus_tok_free_failures", { max: 1000 })),
    freeFailuresDays: Math.round(n("cyrus_tok_free_failures_days", { min: 1, max: 90 })),
    dailyCap: Math.round(n("cyrus_tok_daily_spend_cap", { min: 1 })),
    newAccountDays: Math.round(n("cyrus_tok_new_account_days", { max: 365 })),
    newAccountDailyCap: Math.round(n("cyrus_tok_new_account_daily_cap", { min: 1 })),
    lowBalance: Math.round(n("cyrus_tok_low_balance")),
    starterTokens: Math.round(n("cyrus_tok_starter", { max: 100000 })),
    starterDays: Math.round(n("cyrus_tok_starter_days", { min: 1, max: 365 })),
    grant: {
      initial: {
        base: n("cyrus_tok_grant_initial_base"), perUsd: n("cyrus_tok_grant_initial_per_usd"),
        min: n("cyrus_tok_grant_initial_min"), max: n("cyrus_tok_grant_initial_max"),
      },
      renew: {
        base: n("cyrus_tok_grant_renew_base"), perUsd: n("cyrus_tok_grant_renew_per_usd"),
        min: n("cyrus_tok_grant_renew_min"), max: n("cyrus_tok_grant_renew_max"),
      },
      termMonthsCap: Math.round(n("cyrus_tok_grant_term_months_cap", { min: 1, max: 36 })),
      expiryDays: Math.round(n("cyrus_tok_grant_expiry_days", { min: 1, max: 3650 })),
      maxInitialPer30d: Math.round(n("cyrus_tok_grant_max_initial_per_30d", { max: 1000 })),
      balanceCap: Math.round(n("cyrus_tok_grant_balance_cap")),
    },
    plan: {
      tokens: {
        katara: Math.round(n("cyrus_tok_plan_katara_tokens")),
        saka: Math.round(n("cyrus_tok_plan_saka_tokens")),
        all: Math.round(n("cyrus_tok_plan_all_tokens")),
      },
      cents: {
        katara: Math.round(n("cyrus_tok_plan_katara_cents", { min: 1 })),
        saka: Math.round(n("cyrus_tok_plan_saka_cents", { min: 1 })),
        all: Math.round(n("cyrus_tok_plan_all_cents", { min: 1 })),
      },
      rolloverMonths: n("cyrus_tok_plan_rollover_months", { min: 1, max: 120 }),
      cancelGraceDays: Math.round(n("cyrus_tok_plan_cancel_grace_days", { max: 3650 })),
      pastDueGraceDays: Math.round(n("cyrus_tok_plan_past_due_grace_days", { max: 60 })),
      priceIds: {
        katara: (g("cyrus_tok_price_katara") ?? "").trim(),
        saka: (g("cyrus_tok_price_saka") ?? "").trim(),
        all: (g("cyrus_tok_price_all") ?? "").trim(),
      },
    },
    topup: {
      enabled: b("cyrus_tok_topup_enabled"),
      tokensPerUsd: n("cyrus_tok_topup_tokens_per_usd", { min: 1 }),
      minCents: Math.round(n("cyrus_tok_topup_min_cents", { min: 50 })),
      maxCents: Math.round(n("cyrus_tok_topup_max_cents", { min: 50, max: 99999999 })),
      expiryDays: Math.round(n("cyrus_tok_topup_expiry_days", { min: 1, max: 3650 })),
      requiresPaid: b("cyrus_tok_topup_requires_paid"),
    },
    adminGrantExpiryDays: Math.round(n("cyrus_tok_admin_grant_expiry_days", { min: 1, max: 3650 })),
  };
}

let cache: { cfg: TokenConfig; at: number } | null = null;

/** Server only: the live config (30 s in-process cache; `fresh` bypasses it). */
export async function loadTokenConfig(fresh = false): Promise<TokenConfig> {
  if (!fresh && cache && Date.now() - cache.at < 30_000) return cache.cfg;
  const { db } = await import("../../db");
  const rows = await db.setting.findMany({ where: { key: { startsWith: "cyrus_tok_" } } });
  const cfg = parseTokenConfig(Object.fromEntries(rows.map((r) => [r.key, r.value])));
  cache = { cfg, at: Date.now() };
  return cfg;
}

export function clearTokenConfigCache() { cache = null; }
// Creating a mod build (the AI Mod Builder / Cyrus): validation, rate limits, the Cyrus token
// gate, the DB row, attachments and the hand-off to the build service. Shared by
// POST /api/mod-builder/builds and the Cyrus forge stream (POST /api/cyrus/generate), so both
// enforce exactly the same rules. Server only.
import { promptProblem } from "../cyrus/prompt-check";
import { randomBytes } from "node:crypto";
import type { User } from "@prisma/client";
import { db } from "@/lib/db";
import { svcCreate, ModBuilderUnavailable } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { MB_VERSIONS, type ModBuildView } from "@/lib/modbuilder/types";
import { checkRateLimit } from "@/lib/rate-limit";
import { isCyrusModel } from "@/lib/cyrus/models";
import { readCyrusMeta, type CyrusMeta } from "@/lib/cyrus/meta";
import { claimUploads, isUploadId, readAttachment } from "@/lib/cyrus/uploads";
import type { CyrusAttachment } from "@/lib/cyrus/meta";
import { gateBuild, releaseBuildTokens } from "@/lib/cyrus/tokens/builds";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";
import { cyrusSuspension } from "@/lib/cyrus/suspensions";
import { cyrusGameBuildable } from "@/lib/cyrus/game-status.server";

const MAX_INFLIGHT = 2;

export type CreateBuildResult =
  | { ok: true; status: 201; build: ModBuildView; reserved: number | null }
  | { ok: false; status: number; json: Record<string, unknown> };

const fail = (status: number, json: Record<string, unknown>): CreateBuildResult => ({ ok: false, status, json });

/** `body` is the JSON the API takes: { prompt, mcVersion, changeRequest, baseBuildId, model, attachmentIds, retarget? }. */
export async function createModBuild(user: User, body: Record<string, unknown>): Promise<CreateBuildResult> {
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;
  // Cyrus (optional, additive): the model picked in the composer and pasted images.
  if (body.model !== undefined && !isCyrusModel(body.model)) return fail(400, { error: "Pick Katara, Saka or Yakko." });
  const attachmentIds = Array.isArray(body.attachmentIds) ? body.attachmentIds.filter(isUploadId).slice(0, 4) : [];

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return fail(400, { error: "Pick a Minecraft version from the list." });

  let base = null;
  if (baseBuildId) {
    base = await db.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return fail(404, { error: "Not found" });
    if (base.status !== "succeeded") return fail(400, { error: "You can only change a build that finished." });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return fail(400, { error: "Describe the change in a few words (up to 2,000 characters)." });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return fail(400, { error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." });
  }

  // Not a mod request (gibberish, "Yo Yo Yo", repetition, only symbols): refuse BEFORE tokens are held or the
  // AI is called. Free, instant, and never charged (lib/cyrus/prompt-check.ts).
  const unclear = promptProblem(base ? changeRequest : prompt);
  if (unclear) return fail(400, { error: unclear, code: "prompt_unclear" });

  // Cyrus admin (/admin/cyrus): an account suspended from building, or Minecraft switched off.
  if (await cyrusSuspension(user.id, "build")) return fail(403, { error: "Cyrus building is paused on this account. Contact support if you think this is a mistake.", code: "suspended" });
  if (!(await cyrusGameBuildable("minecraft"))) return fail(503, { error: "Cyrus building for Minecraft is paused right now. Please try again later.", code: "game_disabled" });

  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return fail(429, { error: `You're building fast! Try again in ${rl.retryAfterSec}s.` });
  }
  const inflight = await db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return fail(429, { error: "You already have builds running. Wait for one to finish first." });

  const id = "mb" + randomBytes(10).toString("hex");
  // Cyrus tokens (lib/cyrus/tokens/builds.ts): pick the model the account may use and hold
  // tokens for this build before anything is created. A change keeps the model its version
  // was built with unless a new one is picked (or that model is no longer unlocked).
  const gate = await gateBuild({
    user, buildId: id,
    requested: isCyrusModel(body.model) ? body.model : undefined,
    baseModel: base ? readCyrusMeta(base.cyrus).model : undefined,
    text: base ? `${base.prompt}\n${changeRequest}` : prompt,
  });
  if (!gate.ok) return fail(gate.status, { error: gate.error, code: gate.code, need: gate.need, available: gate.available, model: gate.model });
  const model = gate.model;
  const cyrus: CyrusMeta | null = model || attachmentIds.length ? { ...(model ? { model } : {}) } : null;
  const row = await db.modBuild.create({
    data: {
      id,
      userId: user.id,
      prompt: base ? base.prompt : prompt,
      changeRequest: base ? changeRequest : null,
      baseBuildId: base ? base.id : null,
      rootBuildId: base ? (base.rootBuildId ?? base.id) : id,
      // A change keeps its base's version, unless it is a RETARGET (Cyrus lifecycle: "Update with
      // Cyrus for the new version"), which rebuilds the same mod for another supported version.
      mcVersion: base ? (body.retarget === true ? mcVersion : base.mcVersion) : mcVersion,
      pluginName: base ? base.pluginName : null,
      ...(cyrus ? { cyrus } : {}),
    },
  });
  let attachments: CyrusAttachment[] = [];
  if (attachmentIds.length) {
    attachments = await claimUploads(user.id, id, attachmentIds).catch(() => []);
    if (attachments.length) await db.modBuild.update({ where: { id }, data: { cyrus: { ...(cyrus ?? {}), attachments } } });
  }
  // Cyrus reads the pasted images: their bytes go to the build service (0.4+), which puts
  // them in the build workspace for the model to look at. Already type-sniffed + size-capped.
  const images = (await Promise.all(attachments.map(async (a) => {
    const buf = await readAttachment(id, a).catch(() => null);
    return buf ? { name: a.name, type: a.type, data: buf.toString("base64") } : null;
  }))).filter((x): x is { name: string; type: string; data: string } => !!x);
  try {
    await svcCreate({
      id,
      prompt: row.prompt,
      mcVersion: row.mcVersion,
      // A fork copy ("Build on this mod") is based on the ORIGINAL build the service holds.
      ...(base ? { baseBuildId: await serviceBuildId(base.id), changeRequest } : {}),
      ...(model ? { tier: model } : {}),
      ...(images.length ? { images } : {}),
    });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    if (gate.tracked) await releaseBuildTokens(id);
    console.error("[modbuilder] create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: base ? "modbuilder.change" : "modbuilder.build", detail: id } }).catch(() => {});
  const fresh = await db.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: gate.reserved };
}

// Version-support registry: the one place that says what each Minecraft version needs (JDK, pack formats,
// capabilities) and whether Cyrus may build for it. Replaces scattered version lists and the old packFormatFor.
// Data lives in registry.json so the Next.js app and the plain-Node build service can read the same file.
import registryData from "./registry.json";

export type Capability = "itemModelDefinitions" | "dialogApi" | "adventure5" | "dataComponentsStable";
export type FormatVersion = { major: number; minor: number };
export type VersionRow = {
  id: string;
  family: "1.21" | "26";
  javaRelease: 21 | 25;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  paperCoordinate: string | null;
  resourcePack: FormatVersion | null;
  dataPack: FormatVersion | null;
  resourcePackClientVerified: boolean;
  capabilities: Capability[];
};

export const VERSIONS: readonly VersionRow[] = registryData.versions as VersionRow[];

/** Exact match only: a version the registry does not list is unknown, never guessed. */
export function getVersion(id: string): VersionRow | null {
  return VERSIONS.find((v) => v.id === id) ?? null;
}

export const buildableVersions = (): VersionRow[] => VERSIONS.filter((v) => v.buildable);
export const hasCapability = (id: string, c: Capability): boolean => !!getVersion(id)?.capabilities.includes(c);

export type PackFormatResult =
  | { ok: true; format: FormatVersion; clientVerified: boolean }
  | { ok: false; error: string };

/** Resource-pack format for a version. Fails closed: unknown version, unknown number, or no item-model support. */
export function resourcePackFormat(mc: string, opts: { needsItemModels?: boolean } = {}): PackFormatResult {
  const v = getVersion(mc);
  if (!v) return { ok: false, error: `Minecraft ${mc} is not in the version registry` };
  if (!v.resourcePack) return { ok: false, error: `resource pack format for ${mc} is not verified yet` };
  if (opts.needsItemModels && !v.capabilities.includes("itemModelDefinitions")) {
    return { ok: false, error: `${mc} has no item model definitions (needs 1.21.4+); a legacy custom-model-data emitter is not built yet` };
  }
  return { ok: true, format: v.resourcePack, clientVerified: v.resourcePackClientVerified };
}
{
  "schema": 1,
  "updated": "2026-10-10",
  "source": "research/E-versions.md + C-texture.md (pack formats from minecraft.wiki Pack_format as read by the research agents, 2026-10-10)",
  "notes": [
    "resourcePack/dataPack are major.minor. null = not verified: consumers must fail closed.",
    "resourcePackClientVerified=false everywhere: no pack has yet been loaded in a real client from this registry. 26.x stays preview until that check (a real-client test) passes.",
    "javaRelease 25 for 26.x; paperCoordinate for 26.x is null on purpose: pin an EXACT STABLE build (the newest 26.3 build was beta on 2026-10-09; floating coordinates are unsafe).",
    "buildable=true only for versions the build service really compiles today (JDK 21 + javac --release 21). Set buildable only after eval + runtime load pass."
