  fullId    String
  codepoint Int?     @unique
  createdAt DateTime @default(now())

  @@unique([namespace, kind, key])
  @@index([projectId])
}

// ---------------------------------------------------------------------------
// Cyrus token economy'''
s=s.replace(anchor, block)
open(p,'w').write(s)
