// Cyrus engine core (R0): ModSpec validation + migrations, identifiers + collisions, the capability router and the
// plan-tier asset gate (full matrix). Pure: no DB, no network. Run: tsx --test test/cyrus-engine-core.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { validateModSpec, migrateSpec, modSpecJsonSchema, type ModSpec } from "../lib/cyrus/engine-core/spec";
import {
  NAMESPACE_RE, namespaceFromSeed, buildIdentifier, parseIdentifier, validateIdentifier, nextGlyph, glyphBlockStart,
  glyphHomeBlock, isGlyphCodepoint, detectCollisions, GLYPH_BLOCK, GLYPH_BLOCKS, IDENTIFIER_KINDS,
} from "../lib/cyrus/engine-core/identifiers";
import { routeSpec } from "../lib/cyrus/engine-core/router";
import { canAsset, normalizePlan, planFromTokenState, assetOpForSource, downgradeSpecAssets, gateSpecAssets, ASSET_OPS } from "../lib/cyrus/engine-core/asset-gate";
import { diffManifests, validateManifest, validateEngineRecord, isSafeProjectPath } from "../lib/cyrus/engine-core/revisions";
import { getAdapter, ADAPTERS } from "../lib/cyrus/adapters";
import { minecraftAdapter as MC } from "../lib/cyrus/adapters/minecraft";
import { VERSIONS } from "../lib/cyrus/versions/registry";

const NS = "nx_abcd1234";
const raw = (over: Record<string, unknown> = {}) => ({
  schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: NS,
  summary: "A coin shop with a chest menu and /pay",
  routes: ["plugin"],
  requirements: [{ id: "REQ-1", text: "Players can /pay each other coins" }],
  tests: [{ id: "T-1", kind: "compile", description: "The plugin compiles", covers: ["REQ-1"] }],
  install: { side: "server", restartRequired: true },
  ...over,
});
const V = (r: unknown) => validateModSpec(r, { adapterFor: getAdapter });
const spec = (over: Record<string, unknown> = {}): ModSpec => {
  const v = V(raw(over));
  if (!v.ok) throw new Error(JSON.stringify(v.errors));
  return v.spec;
};
const codes = (r: ReturnType<typeof V>) => (r.ok ? [] : r.errors.map((e) => e.code));
const warns = (r: ReturnType<typeof V>) => r.warnings.map((w) => w.code);

describe("ModSpec v1", () => {
  it("accepts a minimal spec and fills defaults", () => {
    const r = V(raw());
    assert.ok(r.ok, JSON.stringify(r));
    assert.equal(r.spec.requirements[0].priority, "must");
    assert.deepEqual(r.spec.assets, []);
    assert.deepEqual(r.spec.nonGoals, []);
    assert.deepEqual(r.warnings, []);
    assert.equal(r.migratedFrom, 1);
  });
  it("rejects a missing, bad or too-new schemaVersion", () => {
    const { schemaVersion: _, ...noVer } = raw();
    assert.deepEqual(codes(V(noVer)), ["missing_schema_version"]);
    assert.deepEqual(codes(V(raw({ schemaVersion: 2 }))), ["schema_too_new"]);
    assert.deepEqual(codes(V(raw({ schemaVersion: 1.5 }))), ["bad_schema_version"]);
    assert.deepEqual(codes(V(raw({ schemaVersion: 0 }))), ["no_migration"]);
    assert.deepEqual(codes(V("nope")), ["not_object"]);
  });
  it("runs the migration hook in order", () => {
    const migrations = { 0: (d: Record<string, unknown>) => { const { reqs, ...rest } = d; return { ...rest, requirements: reqs }; } };
    const { requirements, ...v0 } = raw({ schemaVersion: 0 });
    const m = migrateSpec({ ...v0, reqs: requirements }, migrations);
    assert.ok(m.ok);
    assert.deepEqual(m.applied, [0]);
    const r = validateModSpec({ ...v0, reqs: requirements }, { adapterFor: getAdapter, migrations });
    assert.ok(r.ok);
    assert.equal(r.migratedFrom, 0);
    assert.equal(r.spec.schemaVersion, 1);
  });
  it("returns structured errors with paths", () => {
    const r = V(raw({ requirements: [{ id: "R1", text: "x" }], extra: true }));
    assert.equal(r.ok, false);
    const paths = r.ok ? [] : r.errors.map((e) => e.path);
    assert.ok(paths.includes("requirements[0].id"), paths.join());
    assert.ok(paths.includes("requirements[0].text"), paths.join());
    assert.ok(codes(r).includes("unrecognized_keys"));
    assert.ok(!V(raw({ namespace: "minecraft" })).ok);
    assert.ok(!V(raw({ routes: [] })).ok);
    assert.ok(!V(raw({ routes: ["shader"] })).ok);
  });
  it("checks game and version against the adapter's registry", () => {
    const u = V(raw({ target: { version: "1.20.4" } }));
    assert.deepEqual(codes(u), ["unknown_version"]);
    assert.equal(u.ok ? "" : u.errors[0].path, "target.version");
    assert.deepEqual(codes(V(raw({ game: "valheim" }))), ["unknown_game"]);
    const p = V(raw({ target: { version: "26.1.2" } }));
    assert.ok(p.ok);
    assert.deepEqual(warns(p), ["version_not_buildable"]);
    assert.deepEqual(warns(validateModSpec(raw())), ["unchecked_game"]);
  });
  it("enforces stable unique ids and cross references", () => {
    assert.deepEqual(codes(V(raw({ requirements: [{ id: "REQ-1", text: "one thing" }, { id: "REQ-1", text: "two thing" }] }))), ["duplicate_id"]);
    assert.deepEqual(codes(V(raw({ assets: [{ id: "coin", kind: "texture", purpose: "coin icon", requirementIds: ["REQ-9"] }] }))), ["unknown_requirement"]);
    assert.deepEqual(codes(V(raw({ tests: [{ id: "T-1", kind: "boot", description: "boots", covers: ["REQ-2"] }] }))), ["unknown_requirement"]);
    assert.deepEqual(codes(V(raw({ routes: ["plugin", "plugin"] }))), ["duplicate_id"]);
    assert.deepEqual(warns(V(raw({ tests: [] }))), ["untested_requirement"]);
    assert.deepEqual(warns(V(raw({ routes: ["plugin", "clientMod"] }))), ["route_unsupported"]);
  });
  it("exports a JSON Schema that matches the committed contract file", () => {
    const js = modSpecJsonSchema();
    assert.equal(typeof js.$schema, "string");
    const props = (js.properties ?? {}) as Record<string, unknown>;
    for (const k of ["schemaVersion", "game", "target", "namespace", "summary", "routes", "requirements", "nonGoals", "constraints", "assets", "tests", "install"]) assert.ok(k in props, k);
    const file = JSON.parse(readFileSync(path.join(import.meta.dirname, "..", "lib/cyrus/engine-core/modspec.v1.schema.json"), "utf8"));
    assert.deepEqual(file, js, "regenerate: npx tsx scripts/cyrus-modspec-schema.ts");
  });
});

describe("namespaces + identifiers", () => {
  it("namespaces are deterministic, well-formed and spread", () => {
    assert.equal(namespaceFromSeed("cp123"), namespaceFromSeed("cp123"));
    const seen = new Set<string>();
    for (let i = 0; i < 5000; i++) { const n = namespaceFromSeed(`cp${i}`); assert.match(n, NAMESPACE_RE); seen.add(n); }
    assert.equal(seen.size, 5000);
  });
  it("builds and parses every kind", () => {
    const ok: [typeof IDENTIFIER_KINDS[number], string, string][] = [
      ["item", "ruby_sword", `${NS}:ruby_sword`], ["model", "item/ruby_sword", `${NS}:item/ruby_sword`], ["sound", "mob.banshee.scream", `${NS}:mob.banshee.scream`],
      ["permission", "admin.reload", `${NS}.admin.reload`], ["command", "coins", `${NS}:coins`], ["recipe", "ruby_block", `${NS}:ruby_block`],
      ["glyph", "coin_icon", `${NS}:coin_icon`], ["config", "shop.max-items", `${NS}.shop.max-items`],
    ];
    for (const [k, key, full] of ok) {
      const b = buildIdentifier(NS, k, key);
      assert.deepEqual(b, { ok: true, id: full }, k);
      assert.deepEqual(parseIdentifier(k, full), { namespace: NS, key }, k);
    }
    assert.equal(ok.length, IDENTIFIER_KINDS.length);
  });
  it("rejects bad keys and foreign namespaces", () => {
    for (const [k, key] of [["item", "Ruby"], ["item", ""], ["item", "a".repeat(49)], ["model", "item//x"], ["model", "../x"], ["sound", "a..b"], ["permission", "a b"], ["command", "x:y"]] as const) {
      assert.equal(buildIdentifier(NS, k, key).ok, false, `${k} ${key}`);
    }
    assert.equal(buildIdentifier("minecraft", "item", "stone").ok, false);
    assert.equal(validateIdentifier("item", `${NS}:coin`, NS).ok, true);
    assert.equal(validateIdentifier("item", "nx_zzzz9999:coin", NS).ok, false);
    assert.equal(validateIdentifier("item", "minecraft:stone").ok, false);
  });
  it("allocates glyphs from the home block in the supplementary PUAs", () => {
    const start = glyphBlockStart(glyphHomeBlock(NS));
    assert.equal(nextGlyph(NS, []), start);
    assert.equal(nextGlyph(NS, [start, start + 1]), start + 2);
    const full = Array.from({ length: GLYPH_BLOCK }, (_, i) => start + i);
    assert.equal(nextGlyph(NS, full), glyphBlockStart(glyphHomeBlock(NS) + 1));
    assert.equal(glyphBlockStart(0), 0xf0000);
    assert.equal(glyphBlockStart(255), 0x100000);
    assert.equal(glyphBlockStart(GLYPH_BLOCKS), 0xf0000);
    for (let i = 0; i < GLYPH_BLOCKS; i++) { assert.ok(isGlyphCodepoint(glyphBlockStart(i))); assert.ok(isGlyphCodepoint(glyphBlockStart(i) + GLYPH_BLOCK - 1)); }
    assert.equal(isGlyphCodepoint(0xe000), false);
    assert.equal(isGlyphCodepoint(0xfff00), false);
  });
  it("detects collisions across a set", () => {
    assert.deepEqual(detectCollisions([
      { kind: "item", id: `${NS}:coin`, owner: "a" }, { kind: "sound", id: `${NS}:coin`, owner: "a" }, { kind: "item", id: "nx_bbbb2222:coin", owner: "b" },
    ]), []);
    const c = detectCollisions([
      { kind: "item", id: `${NS}:coin`, owner: "a" }, { kind: "item", id: `${NS}:COIN`, owner: "b" },
      { kind: "glyph", id: `${NS}:g1`, codepoint: 0xf0000, owner: "a" }, { kind: "glyph", id: "nx_bbbb2222:g1", codepoint: 0xf0000, owner: "b" },
      { kind: "item", id: "minecraft:stone", owner: "c" },
    ]);
    assert.deepEqual(c.map((x) => x.type).sort(), ["duplicate_codepoint", "duplicate_id", "invalid_id"]);
    const dup = c.find((x) => x.type === "duplicate_id");
    assert.deepEqual(dup && "owners" in dup ? dup.owners : [], ["a", "b"]);
  });
});

describe("revision manifests (pure)", () => {
  const h = (c: string) => c.repeat(64);
  it("validates and sorts manifests", () => {
    const m = validateManifest([{ path: "src/b.java", sha256: h("b"), role: "source" }, { path: "plugin.yml", sha256: h("a"), role: "config" }]);
    assert.ok(m.ok);
    assert.deepEqual(m.entries.map((e) => e.path), ["plugin.yml", "src/b.java"]);
    for (const bad of [[{ path: "/etc/passwd", sha256: h("a"), role: "source" }], [{ path: "a/../b", sha256: h("a"), role: "source" }], [{ path: "a", sha256: "xyz", role: "source" }], [{ path: "a", sha256: h("a"), role: "binary" }], [{ path: "a", sha256: h("a"), role: "source" }, { path: "a", sha256: h("b"), role: "source" }], {}]) {
      assert.equal(validateManifest(bad).ok, false, JSON.stringify(bad));
    }
    assert.equal(isSafeProjectPath("a\\b"), false);
  });
  it("diffs added, removed and changed files", () => {
    const a = [{ path: "x", sha256: h("1"), role: "source" as const }, { path: "y", sha256: h("2"), role: "source" as const }, { path: "z", sha256: h("3"), role: "config" as const }];
    const b = [{ path: "x", sha256: h("1"), role: "source" as const }, { path: "y", sha256: h("9"), role: "source" as const }, { path: "w", sha256: h("4"), role: "asset" as const }];
    const d = diffManifests(a, b);
    assert.deepEqual(d.added.map((e) => e.path), ["w"]);
    assert.deepEqual(d.removed.map((e) => e.path), ["z"]);
    assert.deepEqual(d.changed.map((e) => e.path), ["y"]);
    assert.equal(d.unchanged, 1);
    assert.deepEqual(diffManifests(a, a), { added: [], removed: [], changed: [], unchanged: 3 });
  });
  it("validates engine records", () => {
    assert.ok(validateEngineRecord({ promptVersion: "mb-2026-10-09.1", sheets: [{ name: "1.21.11.md", sha256: h("c") }], imageDigest: "sha256:abc" }).ok);
    assert.ok(validateEngineRecord(undefined).ok);
    assert.equal(validateEngineRecord({ secret: "x" }).ok, false);
    assert.equal(validateEngineRecord({ sheets: [{ name: 1 }] }).ok, false);
  });
});

describe("Minecraft adapter", () => {
  it("is registered and mirrors the version registry exactly", () => {
    assert.equal(getAdapter("minecraft"), MC);
    assert.equal(ADAPTERS.length, 1);
    assert.deepEqual(MC.versions.list().map((v) => v.id), VERSIONS.map((v) => v.id));
    for (const v of VERSIONS) {
      assert.equal(MC.versions.get(v.id)?.buildable, v.buildable);
      assert.equal(MC.toolchain.releaseFor(v.id), v.buildable ? String(v.javaRelease) : null);
    }
    assert.equal(MC.versions.get("1.20.4"), null);
  });
  it("is honest: only the plugin route is available today", () => {
    assert.deepEqual(MC.artifacts.filter((a) => a.availability === "available").map((a) => a.route), ["plugin"]);
    assert.equal(MC.artifacts.find((a) => a.route === "clientMod")?.availability, "unsupported");
    assert.equal(MC.testLane.boot, "planned");
  });
});

describe("capability router", () => {
  const R = (over: Record<string, unknown> = {}, opts: Parameters<typeof routeSpec>[2] = {}) => routeSpec(spec(over), MC, opts);
  const ids = (d: ReturnType<typeof R>) => d.limits.map((l) => l.id);
  it("routes a plain plugin request with no limits", () => {
    const d = R();
    assert.equal(d.label, "plugin");
    assert.ok(d.buildableNow);
    assert.deepEqual(d.limits, []);
  });
  it("adds a resource pack for custom assets and says it is not built yet", () => {
    const d = R({ assets: [{ id: "coin", kind: "texture", purpose: "coin item icon" }] });
    assert.equal(d.label, "plugin+resourcePack");
    assert.deepEqual(d.planned, ["resourcePack"]);
    assert.equal(d.buildableNow, false);
    assert.ok(ids(d).includes("route:resourcePack"));
  });
  it("custom blocks, free-form HUD and keybinds need a client mod", () => {
    for (const text of ["Add a custom block called ruby ore", "Show a minimap in the corner", "Open the shop with a custom keybind"]) {
      const d = R({ requirements: [{ id: "REQ-1", text }] });
      assert.deepEqual(d.unsupported, ["clientMod"], text);
      assert.equal(d.label, "plugin", text);
      assert.ok(ids(d).includes("route:clientMod"), text);
    }
    const only = R({ routes: ["clientMod"], summary: "A brand-new block type that glows", requirements: [{ id: "REQ-1", text: "Custom blocks that glow" }] });
    assert.equal(only.label, "clientMod-unsupported");
    assert.ok(ids(only).includes("custom_block"));
  });
  it("non-goals and constraints never trigger a route", () => {
    const d = R({ nonGoals: ["No custom blocks", "No minimap"], constraints: ["Must not need custom keybinds"] });
    assert.equal(d.label, "plugin");
    assert.deepEqual(d.limits, []);
  });
  it("checks version capabilities: Dialog API 1.21.7+, item models 1.21.4+", () => {
    const dlg = (v: string) => R({ target: { version: v }, requirements: [{ id: "REQ-1", text: "Open a dialog to confirm a purchase" }] });
    const old = dlg("1.21.4");
    const block = old.limits.find((l) => l.id === "dialog:version");
    assert.equal(block?.severity, "block");
    assert.match(block!.message, /1\.21\.7/);
    assert.match(block!.message, /1\.21\.4/);
    assert.equal(old.buildableNow, false);
    assert.ok(!ids(dlg("1.21.8")).includes("dialog:version"));
    const tex = (v: string) => R({ target: { version: v }, assets: [{ id: "ruby", kind: "model", purpose: "ruby sword model" }] });
    assert.ok(ids(tex("1.21.1")).includes("item_model:version"));
    assert.ok(!ids(tex("1.21.4")).includes("item_model:version"));
  });
  it("worldgen goes to a data pack and warns about the restart", () => {
    const d = R({ requirements: [{ id: "REQ-1", text: "Add a crystal biome with new structures" }] });
    assert.deepEqual(d.routes, ["plugin", "dataPack"]);
    assert.match(d.limits.find((l) => l.id === "worldgen")!.message, /restart/);
    const only = R({ routes: ["dataPack"], summary: "Add loot tables for dungeon chests", requirements: [{ id: "REQ-1", text: "Dungeon chests drop rubies" }] });
    assert.equal(only.label, "dataPack");
  });
  it("a preview version is routed but never buildable", () => {
    const d = R({ target: { version: "26.1.2" } });
    assert.ok(ids(d).includes("version:not_buildable"));
    assert.equal(d.buildableNow, false);
  });
  it("applies the plan gate by downgrading, never by erroring", () => {
    const over = { assets: [{ id: "coin", kind: "texture", purpose: "coin item icon" }, { id: "ding", kind: "sound", purpose: "coin pickup sound" }] };
    const k = R(over, { gate: { plan: "katara" } });
    assert.deepEqual(k.removedAssets.map((r) => r.assetId), ["coin", "ding"]);
    assert.deepEqual(k.spec.assets, []);
    assert.equal(k.label, "plugin");
    assert.ok(ids(k).includes("asset_gate:coin") && ids(k).includes("asset_gate:ding"));
    const s = R(over, { gate: { plan: "saka" } });
    assert.deepEqual(s.removedAssets.map((r) => r.assetId), ["coin"]);
    assert.equal(s.label, "plugin+resourcePack");
    const all = R(over, { gate: { plan: "yakko" } });
    assert.deepEqual(all.removedAssets, []);
    const unknown = R(over, { gate: { plan: undefined } });
    assert.deepEqual(unknown.removedAssets.map((r) => r.code), ["plan_unknown", "plan_unknown"]);
    const kept = R({ assets: [{ id: "coin", kind: "texture", purpose: "coin item icon", source: "existing" }] }, { gate: { plan: "free" } });
    assert.deepEqual(kept.removedAssets, []);
    assert.equal(kept.label, "plugin+resourcePack");
  });
  it("a gated asset asked for only in words adds a plan notice, not a route", () => {
    const d = R({}, { prompt: "and give it custom sounds", gate: { plan: "katara" } });
    assert.equal(d.label, "plugin");
    assert.ok(ids(d).includes("custom_sound:plan"));
    const s = R({}, { prompt: "and give it custom sounds", gate: { plan: "saka" } });
    assert.equal(s.label, "plugin+resourcePack");
  });
  it("is deterministic", () => {
    const over = { requirements: [{ id: "REQ-1", text: "A dialog shop with custom textures and a biome" }] };
    assert.deepEqual(R(over, { gate: { plan: "all" } }), R(over, { gate: { plan: "all" } }));
  });
});

describe("asset gate: full matrix (4 plans x texture/sound x create/edit/keep/install/export)", () => {
  const plans = ["free", "katara", "saka", "all"] as const;
  const expectCreate: Record<string, Record<string, boolean>> = {
    texture: { free: false, katara: false, saka: false, all: true },
    sound: { free: false, katara: false, saka: true, all: true },
  };
  for (const plan of plans) for (const kind of ["texture", "sound"] as const) for (const op of ["create", "edit", "keep", "install", "export"] as const) {
    const want = op === "create" || op === "edit" ? expectCreate[kind][plan] : true;
    it(`${plan} ${kind} ${op} -> ${want ? "allow" : "deny"}`, () => {
      const d = canAsset(plan, kind, op);
      assert.equal(d.ok, want);
      if (!d.ok) { assert.equal(d.code, "asset_locked"); assert.equal(d.needs, kind === "sound" ? "saka" : "all"); }
    });
  }
  it("model and ui follow the texture studio (top plan)", () => {
    for (const kind of ["model", "ui"] as const) for (const plan of plans) assert.equal(canAsset(plan, kind, "create").ok, plan === "all", `${plan} ${kind}`);
  });
  it("rebuild, import and compose (Mod Packs) are never gated, for any plan or none", () => {
    for (const plan of [...plans, null, undefined, "gold"]) for (const kind of ["texture", "sound", "model", "ui"] as const) for (const op of ["keep", "install", "export", "rebuild", "import", "compose"] as const) {
      assert.ok(canAsset(plan, kind, op).ok, `${plan} ${kind} ${op}`);
    }
  });
  it("an unknown plan or token state fails closed for create/edit only", () => {
    for (const plan of [null, undefined, "", "gold", 42, {}, "free "]) {
      const p = normalizePlan(plan);
      for (const op of ["create", "edit"] as const) {
        const d = canAsset(plan, "sound", op);
        if (p) assert.equal(d.ok, false); else { assert.equal(d.ok, false); assert.equal(!d.ok && d.code, "plan_unknown"); }
      }
    }
    assert.equal(planFromTokenState(null), null);
    assert.equal(planFromTokenState({}), null);
    assert.equal(planFromTokenState({ tier: "saka" }), "saka");
  });
  it("reconciles plan names in one mapping", () => {
    assert.equal(normalizePlan("yakko"), "all");
    assert.equal(normalizePlan("ALL"), "all");
    assert.equal(normalizePlan("All models"), "all");
    assert.equal(normalizePlan(" Saka "), "saka");
    assert.equal(normalizePlan("katara"), "katara");
    assert.equal(normalizePlan("pro"), null);
  });
  it("rejects unknown ops and kinds", () => {
    assert.equal(canAsset("all", "texture", "delete" as never).ok, false);
    assert.equal(canAsset("all", "shader" as never, "create").ok, false);
    assert.equal(ASSET_OPS.length, 8);
  });
  it("maps spec asset sources to operations", () => {
    assert.deepEqual(["generate", "library", "upload", "edit", "existing", "imported"].map((s) => assetOpForSource(s as never)), ["create", "create", "create", "edit", "keep", "import"]);
  });
  it("downgrade strips only gated slots and leaves the input untouched", () => {
    const s = spec({ assets: [
      { id: "a", kind: "texture", purpose: "new texture", source: "generate" },
      { id: "b", kind: "texture", purpose: "edited texture", source: "edit" },
      { id: "c", kind: "texture", purpose: "kept texture", source: "existing" },
      { id: "d", kind: "sound", purpose: "imported sound", source: "imported" },
      { id: "e", kind: "sound", purpose: "library sound", source: "library" },
    ] });
    const d = downgradeSpecAssets(s, "saka");
    assert.deepEqual(d.removed.map((r) => r.assetId), ["a", "b"]);
    assert.deepEqual(d.spec.assets.map((a) => a.id), ["c", "d", "e"]);
    assert.equal(d.notices.length, 2);
    assert.match(d.notices[0], /All models plan/);
    assert.equal(s.assets.length, 5);
    assert.deepEqual(gateSpecAssets(s, "free").map((r) => r.assetId), ["a", "b", "e"]);
    assert.equal(downgradeSpecAssets(s, "all").spec, s);
  });
});

